CREATE OR REPLACE FUNCTION public.fn_audit_club_entry_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_action text; v_club uuid; v_target uuid; v_actor uuid; v_details jsonb;
BEGIN
  IF TG_TABLE_NAME='clubs' THEN
    v_action:='club_created'; v_club:=NEW.id; v_target:=NEW.id;
    v_actor:=COALESCE(auth.uid(),NEW.owner_id);
    v_details:=jsonb_build_object('club_code',NEW.club_id,'requires_approval',NEW.requires_approval);
  ELSIF TG_TABLE_NAME='club_members' THEN
    v_club:=NEW.club_id; v_target:=NEW.user_id;
    v_actor:=COALESCE(auth.uid(),NEW.user_id);
    v_action:=CASE WHEN TG_OP='INSERT' THEN 'club_join_'||NEW.status ELSE 'club_join_status_changed' END;
    v_details:=jsonb_build_object('status',NEW.status,'previous_status',CASE WHEN TG_OP='UPDATE' THEN OLD.status ELSE NULL END);
  ELSE
    v_action:='player_search_privacy_changed'; v_target:=NEW.user_id;
    v_actor:=COALESCE(auth.uid(),NEW.user_id);
    v_details:=jsonb_build_object('discoverable',NEW.discoverable,'show_presence',NEW.show_presence,'show_current_table',NEW.show_current_table);
  END IF;
  INSERT INTO public.audit_trail(
    club_id,actor_id,actor_role,action,target_type,target_id,after_state
  ) VALUES(
    v_club,v_actor,'system',v_action,TG_TABLE_NAME,v_target,jsonb_strip_nulls(v_details)
  );
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_emit_managed_command_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_club uuid; v_role text := 'host';
BEGIN
  IF OLD.status='processing' AND NEW.status IN ('succeeded','rejected') THEN
    IF NEW.game_kind='table' THEN
      SELECT club_id INTO v_club FROM public.tables WHERE id=NEW.game_id;
    ELSE
      SELECT club_id INTO v_club FROM public.tournaments WHERE id=NEW.game_id;
    END IF;
    PERFORM public.fn_emit_game_management_event(
      'game_command_'||NEW.status,v_club,NULL,NULL,NEW.game_kind,NEW.game_id,
      NEW.command_id,jsonb_build_object('action',NEW.command_action,'status',NEW.status)
    );
    IF EXISTS (SELECT 1 FROM public.union_clubs WHERE club_id=v_club) THEN
      v_role := 'union_admin';
    ELSE
      SELECT CASE WHEN c.owner_id=NEW.actor_id THEN 'owner'
                  WHEN m.role='co_owner' THEN 'co_owner' ELSE 'host' END
        INTO v_role FROM public.clubs c
        LEFT JOIN public.club_members m ON m.club_id=c.id AND m.user_id=NEW.actor_id
       WHERE c.id=v_club;
    END IF;
    INSERT INTO public.audit_trail(
      actor_id,actor_role,action,target_type,target_id,club_id,
      before_state,after_state,reason,request_id
    ) VALUES (
      NEW.actor_id,COALESCE(v_role,'host'),'managed_game_'||NEW.command_action||'_'||NEW.status,
      NEW.game_kind,NEW.game_id,v_club,
      jsonb_build_object('contract_version',NEW.contract_version_before),
      jsonb_build_object('contract_version',NEW.contract_version_after,'result',NEW.result),
      NEW.result->>'reason',NEW.command_id::text
    );
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_emit_managed_schedule_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_kind text := COALESCE(NEW.game_kind, OLD.game_kind);
  v_game uuid := COALESCE(NEW.game_id,   OLD.game_id);
  v_was  boolean := (TG_OP <> 'INSERT' AND OLD.status = 'scheduled');
  v_is   boolean := (TG_OP <> 'DELETE' AND NEW.status = 'scheduled');
  v_club uuid;
BEGIN
  -- Nothing the board renders moved.
  IF NOT v_was AND NOT v_is THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE' AND v_was AND v_is
     AND NEW.execute_at IS NOT DISTINCT FROM OLD.execute_at THEN
    RETURN NULL;
  END IF;

  IF v_kind = 'table' THEN
    SELECT t.club_id INTO v_club FROM public.tables t WHERE t.id = v_game;
  ELSE
    SELECT t.club_id INTO v_club FROM public.tournaments t WHERE t.id = v_game;
  END IF;

  -- The game is gone; its own DELETE already told the board.
  IF v_club IS NULL THEN
    RETURN NULL;
  END IF;

  PERFORM public.fn_emit_game_management_event(
    'game_changed', v_club, NULL, NULL, v_kind, v_game, NULL,
    jsonb_build_object('operation', lower(TG_OP), 'source', 'schedule'));
  RETURN NULL;
END;
$function$
